dtsPropsFor.Button:
children?: React.ReactNode;
/** Visual style. Use at most one primary/accent per view; everything else outline/ghost. */
variant?: "primary" | "accent" | "outline" | "ghost" | "subtle";
size?: "sm" | "md" | "lg";
/** Optional leading icon element rendered before the label. */
icon?: React.ReactNode;
disabled?: boolean;
style?: React.CSSProperties;
onClick?: React.MouseEventHandler<HTMLButtonElement>;
/** Other native <button> attributes are spread onto the element. */
[key: string]: unknown;

dtsPropsFor.Tag:
children?: React.ReactNode;
/** Discipline / topic pill color, e.g. "Data Science", "Biology Education". */
tone?: "navy" | "teal" | "amber" | "coral" | "verdant" | "neutral";
style?: React.CSSProperties;

dtsPropsFor.Badge:
children?: React.ReactNode;
/** Status marker rendered with a leading colored dot. */
status?: "info" | "success" | "warning" | "danger";
style?: React.CSSProperties;

dtsPropsFor.Card:
children?: React.ReactNode;
title?: React.ReactNode;
/** Small uppercase eyebrow label above the title (teal). */
eyebrow?: React.ReactNode;
/** Optional footer strip rendered on a paper-tinted band. */
footer?: React.ReactNode;
/** Optional left-rule accent color for categorization, e.g. "var(--nk-teal)". */
accent?: string | null;
style?: React.CSSProperties;

dtsPropsFor.StatTile:
/** Uppercase overline label above the figure. */
label?: React.ReactNode;
/** The headline figure (serif display face, tabular figures). */
value?: React.ReactNode;
/** Optional unit rendered next to the value, e.g. "%", "ms". */
unit?: string;
/** Change indicator; dir sets color + arrow (up=verdant ▲, down=coral ▼, flat=slate —). */
delta?: { value: string; dir: "up" | "down" | "flat" } | null;
/** Muted note rendered after the delta, e.g. "vs. baseline". */
note?: React.ReactNode;
style?: React.CSSProperties;

dtsPropsFor.DataTable:
/** Column defs. numeric columns render mono + right-aligned with tabular figures. */
columns?: Array<{ key: string; label: React.ReactNode; align?: "left" | "right" | "center"; numeric?: boolean }>;
/** Row objects keyed by column.key. */
rows?: Array<Record<string, React.ReactNode>>;
/** Optional caption rendered above the table. */
caption?: React.ReactNode;
style?: React.CSSProperties;

dtsPropsFor.Callout:
children?: React.ReactNode;
/** Pedagogical aside kind; sets the bar color and default label. */
kind?: "note" | "method" | "caution" | "result";
/** Overrides the default kind label (Note / Method / Caution / Result). */
title?: React.ReactNode;
style?: React.CSSProperties;

dtsPropsFor.Field:
/** Field label rendered above the input. */
label?: React.ReactNode;
/** Muted help text rendered below the input. */
help?: React.ReactNode;
placeholder?: string;
/** Native input type. Default "text". */
type?: string;
value?: string;
onChange?: React.ChangeEventHandler<HTMLInputElement>;
style?: React.CSSProperties;
/** Other native <input> attributes are spread onto the element. */
[key: string]: unknown;

dtsPropsFor.CitationBlock:
/** The reference text, rendered as an APA-style hanging indent. */
children?: React.ReactNode;
/** DOI without the https://doi.org/ prefix; rendered as a trailing link. */
doi?: string | null;
style?: React.CSSProperties;

dtsPropsFor.BrandLockup:
/** Compact variant hides the role line and shrinks the nucleus mark. */
compact?: boolean;
style?: React.CSSProperties;

dtsPropsFor.ChartFrame:
/** Figure number; rendered as "Figure N." before the title. */
figureNumber?: number;
/** Figure caption, rendered italic after the figure number. */
title?: React.ReactNode;
/** Source line rendered under the figure, prefixed "Source.". */
source?: React.ReactNode;
/** The chart/figure content (Recharts, SVG, etc.). */
children?: React.ReactNode;
style?: React.CSSProperties;
